#!/usr/bin/env python3
"""Condense a captured conversation JSONL into a readable digest.

argv: <jsonl path> [max chars per text block]
"""
import json, sys

path = sys.argv[1]
CAP = int(sys.argv[2]) if len(sys.argv) > 2 else 700


def clip(s, n=CAP):
    s = ' '.join(str(s).split())
    return s if len(s) <= n else s[:n] + f' …[{len(s)-n} more]'


with open(path) as fh:
    for line in fh:
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        t = d.get('timestamp', '')[11:19]
        kind = d.get('type')
        if kind == 'queue-operation':
            print(f'[{t}] QUEUE({d.get("operation")}): {clip(d.get("content",""))}')
            continue
        if kind == 'attachment':
            continue
        msg = d.get('message') or {}
        role = msg.get('role') or kind
        content = msg.get('content')
        usage = msg.get('usage') or {}
        if isinstance(content, str):
            print(f'[{t}] {role.upper()}: {clip(content)}')
        elif isinstance(content, list):
            for b in content:
                bt = b.get('type')
                if bt == 'text':
                    print(f'[{t}] {role.upper()}: {clip(b.get("text",""))}')
                elif bt == 'thinking':
                    print(f'[{t}] THINK: {clip(b.get("thinking",""), 400)}')
                elif bt == 'tool_use':
                    print(f'[{t}] TOOL {b.get("name")}: {clip(json.dumps(b.get("input",{})), 400)}')
                elif bt == 'tool_result':
                    c = b.get('content')
                    if isinstance(c, list):
                        c = ' '.join(x.get('text', '') for x in c if isinstance(x, dict))
                    print(f'[{t}] RESULT{"(err)" if b.get("is_error") else ""}: {clip(c, 300)}')
        if usage:
            pass

