// Replay every Bash command captured on this repo's conversation-logs branch
// through the real compiled guard, so the check is judged against real sessions
// rather than the fixtures that were written alongside it.
import { readdirSync, readFileSync, writeFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import { declaredCheck } from '/home/user/Claudinite/engine-tests/helpers.mjs';
import { buildContext } from '/home/user/Claudinite/engine/checks/helpers/repo-context.mjs';
import { runRule } from '/home/user/Claudinite/engine/checks/helpers/work.mjs';

const logs = process.argv[2];
const rule = declaredCheck('.claudinite/local/packs/claudinite', 'mount-path-in-the-canon-home');

const root = mkdtempSync(join(tmpdir(), 'replay-'));
execFileSync('git', ['-C', root, 'init', '-q']);
writeFileSync(join(root, 'a.txt'), 'x\n');
execFileSync('git', ['-C', root, 'add', '.']);
execFileSync('git', ['-C', root, 'commit', '-qm', 'base']);

let sessions = 0; let fired = 0;
for (const f of readdirSync(logs).filter((n) => n.endsWith('.jsonl'))) {
  const lines = readFileSync(join(logs, f), 'utf8').split('\n').filter(Boolean);
  let cwd = null;
  const calls = [];
  for (const l of lines) {
    let d; try { d = JSON.parse(l); } catch { continue; }
    if (d.cwd && !cwd) cwd = d.cwd;
    const content = d.message?.content;
    if (!Array.isArray(content)) continue;
    for (const b of content) {
      if (b.type === 'tool_use' && b.name === 'Bash') calls.push(b.input?.command ?? '');
    }
  }
  if (cwd !== '/home/user/Claudinite') continue; // the guard only mounts here
  sessions += 1;
  const path = join(root, 'transcript.jsonl');
  writeFileSync(path, calls.map((command) => JSON.stringify({
    type: 'assistant', message: { content: [{ type: 'tool_use', name: 'Bash', input: { command } }] },
  })).join('\n') + '\n');
  const findings = runRule(rule, buildContext({ root, mode: 'all', transcriptPath: path }));
  for (const found of findings) { fired += 1; console.log(f.slice(0, 22), '|', found.what); }
}
console.log(`sessions rooted here: ${sessions}; findings: ${fired}`);

